using System.Net.Http.Headers;
using System.Net.Http.Json;
namespace Nova.Client.Core.Networking;
public sealed class ApiClient(HttpClient httpClient,Authentication.ISecureTokenStore tokenStore) { public async Task<T?> GetAsync<T>(string route,CancellationToken ct=default){using var r=new HttpRequestMessage(HttpMethod.Get,route);await AddAuthAsync(r,ct);using var x=await httpClient.SendAsync(r,ct);x.EnsureSuccessStatusCode();return await x.Content.ReadFromJsonAsync<T>(ct);} public async Task<TResponse?> PostAsync<TRequest,TResponse>(string route,TRequest payload,CancellationToken ct=default){using var r=new HttpRequestMessage(HttpMethod.Post,route){Content=JsonContent.Create(payload)};await AddAuthAsync(r,ct);using var x=await httpClient.SendAsync(r,ct);x.EnsureSuccessStatusCode();return await x.Content.ReadFromJsonAsync<TResponse>(ct);} async Task AddAuthAsync(HttpRequestMessage r,CancellationToken ct){var token=await tokenStore.GetAsync(ct);if(!string.IsNullOrWhiteSpace(token))r.Headers.Authorization=new AuthenticationHeaderValue("Bearer",token);} }
